func distances(values [][2]int) string {
	if len(values) == 0 {
		return "-"
	}
	fields := make([]string, len(values))
	for i, v := range values {
		fields[i] = fmt.Sprintf("%d:%d", v[0], v[1])
	}
	return strings.Join(fields, " ")
